import styled from "styled-components";

export const QuickAddContainer = styled.div`
  display: flex;
  margin: 10px;
  align-items: center;
  justify-content: center;
  flex-direction: colUmn;
  min-width: 200px;
  max-width: 20%;
  padding: 10px;
  border: 5px solid #FFECA1;
  border-radius: 5px;
`;

export const Title = styled.div`
  color: #ffffff;
  font-size: 20px;
  line-height: 16px;
  font-weight: 700;
  letter-spacing: 1.4px;
  margin-bottom: 20px;
`;

export const FieldDesc = styled.div`
  color: #ffffff;
  font-size: 12px;
